#include <cstdio>
#include <numeric>
#include <vector>
#include <utility>

using namespace std;

const int MAXN = 10;

int N;
int ar[MAXN];
int fact[MAXN + 1];
int answer;
vector<int> permutation;
vector<unsigned char> seen;

int permutationRank() {
    int rank = 0;
    for (int i = 0; i < N; ++i) {
        int smaller = 0;
        for (int j = i + 1; j < N; ++j)
            if (permutation[j] < permutation[i])
                ++smaller;
        rank += smaller * fact[N - i - 1];
    }
    return rank;
}

void f() {
    int rank = permutationRank();
    if (!seen[rank]) {
        seen[rank] = 1;
        ++answer;
    }

    for (int i = 0; i < N - 1; ++i) {
        if (ar[i] <= 0)
            continue;

        for (int j = i + 1; j < N; ++j) {
            if (ar[j] <= 0)
                continue;

            swap(permutation[i], permutation[j]);
            --ar[i];
            --ar[j];

            f();

            ++ar[i];
            ++ar[j];
            swap(permutation[i], permutation[j]);
        }
    }
}

int main() {
    scanf("%d", &N);

    fact[0] = 1;
    for (int i = 1; i <= N; ++i)
        fact[i] = fact[i - 1] * i;

    for (int i = 0; i < N; ++i)
        scanf("%d", &ar[i]);

    permutation.resize(N);
    iota(permutation.begin(), permutation.end(), 0);
    seen.assign(fact[N], 0);

    f();

    printf("%d\n", answer);
    return 0;
}

